-- Diagnostic wrappers generated by tools/validation/instrument_lua.py; edit bodies normally.
local APRTrace = APRInstrumentation and APRInstrumentation.Wrap or function(_, fn) return fn end
local APRYield = APRInstrumentation and APRInstrumentation.Yield or coroutine.yield
local APRResume = APRInstrumentation and APRInstrumentation.Resume or coroutine.resume
local APRPCall = APRInstrumentation and APRInstrumentation.PCall or pcall
-- Stores and repairs the active leg of a map waypoint journey.

local Constants = APR.NavigationConstants.Navigation

local nav = APR.navigation
local Shared = APR.navigation._helpers
local ActionPending = Shared.ActionPending
local ActionUsable = Shared.ActionUsable
local DepartureAllowed = Shared.DepartureAllowed
local Distance = Shared.Distance
local HasWalkingPath = Shared.HasWalkingPath
local MissingWalkProof = Shared.MissingWalkProof
local Position = Shared.Position
local ReadableLocationValue = Shared.ReadableLocationValue
local SameLocationFields = Shared.SameLocationFields
local TargetMapReached = Shared.TargetMapReached
local WalkingProvider = Shared.WalkingProvider

function nav:RefreshWaypointLeg(start, provider, sameGeometry)
    if not self.waypointJourney or not self:IsItineraryValid() then return end
    local active = self:GetActiveStep()
    if active.kind ~= "walk" then
        if sameGeometry then return true end
        return
    end
    if sameGeometry then
        local _, reachable = self:AdvanceWalkingPath(active, start, provider, true)
        local moved = self:HasPlanningInputsChanged(start)
        if reachable and (HasWalkingPath(active) or not moved) then return true end
    end
    local after = {}
    for index = self.cursor + 1, #self.queue do
        after[#after + 1] = self.queue[index]
    end
    return false, { from = start, to = active.to, after = after, destination = #after == 0 }
end--[[APR_DIAG]]; nav.RefreshWaypointLeg = APRTrace("APR-Core/features/navigation/controller/NavigationWaypointJourney.lua:24:nav:RefreshWaypointLeg#1", nav.RefreshWaypointLeg)--[[/APR_DIAG]]

function nav:SaveWaypointJourney(checkpoint)
    if not self.waypointJourney or type(APRNavigationCharacterSettings) ~= "table" then return end
    local saved = APRNavigationCharacterSettings.waypoint
    if not saved or saved.target ~= self.destination then return end
    local pending = self.waypointPendingLeg
    -- A first-leg repair has no usable departure until it succeeds. Keep the
    -- last saved corridor while this calculation is in flight.
    if pending and not pending.before then return end
    if self.savedWaypointQueue ~= self.queue or not saved.itinerary then
        local segments = {}
        for index, step in ipairs(self.queue) do
            if step.kind == "verify_taxi" or step.exitHousing or (step.kind ~= "walk" and not step.connectionID) then
                saved.itinerary = nil
                return
            end
            segments[index] = {
                id = step.connectionID,
                kind = step.kind,
                from = step.from,
                to = step.to,
                path = step.path,
                seconds = step.seconds,
                copper = step.copper,
                sourceFree = step.sourceFree,
                approachOnly = step.approachOnly,
                arrivalRadius = step.arrivalRadius,
                arrivalZTolerance = step.arrivalZTolerance,
                fromNodeID = step.fromNodeID,
                toNodeID = step.toNodeID,
            }
        end
        saved.itinerary = {
            version = Constants.WAYPOINT_ITINERARY_VERSION,
            addon = APR.version,
            interface = APR.interfaceVersion,
            segments = segments,
        }
        self.savedWaypointQueue = self.queue
    end
    local itinerary = saved.itinerary
    if checkpoint or itinerary.cursor ~= self.cursor then itinerary.position = Position() or itinerary.position end
    itinerary.cursor, itinerary.pending = self.cursor, pending and pending.before == self.queue or nil
    local step, segment = self:GetActiveStep(), itinerary.segments[self.cursor]
    if step and segment then
        segment.pathCursor, segment.departureSeen, segment.boarded = step.pathCursor, step.departureSeen, step.boarded
    end
end--[[APR_DIAG]]; nav.SaveWaypointJourney = APRTrace("APR-Core/features/navigation/controller/NavigationWaypointJourney.lua:43:nav:SaveWaypointJourney#2", nav.SaveWaypointJourney)--[[/APR_DIAG]]

local function SameWaypointConnection(stored, edge)
    return edge
        and stored.kind == edge.kind
        and stored.sourceFree == (edge.sourceFree == true)
        and (stored.sourceFree or SameLocationFields(edge.from, stored.from, Constants.LOCATION_FIELDS))
        and SameLocationFields(edge.to, stored.to, Constants.LOCATION_FIELDS)
end--[[APR_DIAG]]; SameWaypointConnection = APRTrace("APR-Core/features/navigation/controller/NavigationWaypointJourney.lua:91:SameWaypointConnection#3", SameWaypointConnection)--[[/APR_DIAG]]

function nav:GetWaypointResume(saved, start, goal)
    if
        type(saved) ~= "table"
        or saved.version ~= Constants.WAYPOINT_ITINERARY_VERSION
        or saved.addon ~= APR.version
        or saved.interface ~= APR.interfaceVersion
        or type(saved.segments) ~= "table"
        or type(saved.cursor) ~= "number"
        or saved.cursor < 1
        or saved.cursor % 1 ~= 0
    then
        return
    end
    local segments, cursor = saved.segments, saved.cursor
    local last = segments[#segments]
    if not last or not last.to or (not saved.pending and not last.approachOnly and Distance(last.to, goal) > 0.01) then
        return
    end
    local active = segments[cursor]
    local data = APR.NavigationData
    if
        active
        and active.kind ~= "walk"
        and active.departureSeen
        and (active.kind ~= "taxi" or active.boarded)
        and Distance(start, active.to) <= (active.arrivalRadius or (active.kind == "taxi" and 100 or 20))
        and TargetMapReached(start, active.to)
        and (not active.arrivalZTolerance or active.to.z == nil or start.z and math.abs(start.z - active.to.z) <= active.arrivalZTolerance)
        and (not data.IsSameAccessRegion or data:IsSameAccessRegion(start, active.to) == true)
        and not (UnitOnTaxi and UnitOnTaxi("player"))
    then
        cursor, active = cursor + 1, segments[cursor + 1]
    end
    if active and not active.sourceFree and active.from.instanceID ~= start.instanceID then return end
    local resume = { segments = {}, connections = {}, position = saved.position, pending = saved.pending }
    for index = cursor, #segments do
        local segment = segments[index]
        if not segment.from or not segment.to or (segment.kind ~= "walk" and not segment.id) then return end
        resume.segments[#resume.segments + 1] = segment
        if segment.id then resume.connections[segment.id] = true end
        if segment.kind == "taxi" then resume.hasTaxi = true end
    end
    if #resume.segments == 0 then return nil, saved.pending and last.to or nil end
    return resume
end--[[APR_DIAG]]; nav.GetWaypointResume = APRTrace("APR-Core/features/navigation/controller/NavigationWaypointJourney.lua:99:nav:GetWaypointResume#4", nav.GetWaypointResume)--[[/APR_DIAG]]

function nav:JoinWaypointLeg(queue, leg, position)
    local combined, cursor, seconds, copper = {}, 1, 0, 0
    if leg.before then
        cursor = self.waypointPendingLeg == leg and self.queue == leg.before and self.cursor or 1
        for _, step in ipairs(leg.before) do
            combined[#combined + 1] = step
        end
    end
    for _, step in ipairs(queue) do
        combined[#combined + 1] = step
    end
    for _, step in ipairs(leg.after or Constants.EMPTY_GUIDANCE) do
        combined[#combined + 1] = step
    end
    local active, provider = combined[cursor], WalkingProvider()
    if not active then return end
    local published = self.waypointPendingLeg == leg
        and self.queue == leg.before
        and cursor <= #leg.before
        and position
        and (active.sourceFree or position.instanceID == active.from.instanceID)
    local followingTransport = (leg.restored or leg.before and cursor <= #leg.before)
        and active.departureSeen
        and active.kind ~= "walk"
    local checkpoint = leg.restored and SameLocationFields(position, leg.restored.position, Constants.LOCATION_FIELDS)
    if not published and not followingTransport and not checkpoint then
        if not position or (not active.sourceFree and position.instanceID ~= active.from.instanceID) then return end
        local _, reachable = self:AdvanceWalkingPath(active, position, provider, true)
        if not reachable then return end
    end
    for index = cursor, #combined do
        local step = combined[index]
        if MissingWalkProof(step, provider) or DepartureAllowed(step, step.from) ~= true then return end
        if
            step.kind == "walk"
            and not step.connectionID
            and APR.NavigationData:CanWalk(step.from, step.to) == false
        then
            return
        end
        if step.action and not ActionPending(step) and ActionUsable(step.action) == false then return end
        seconds, copper = seconds + (step.seconds or 0), copper + (step.copper or 0)
    end
    local money = GetMoney and GetMoney() or 0
    if ReadableLocationValue(money) and copper > money then return end
    return combined, cursor, seconds, copper
end--[[APR_DIAG]]; nav.JoinWaypointLeg = APRTrace("APR-Core/features/navigation/controller/NavigationWaypointJourney.lua:145:nav:JoinWaypointLeg#5", nav.JoinWaypointLeg)--[[/APR_DIAG]]

APR.navigation._helpers.SameWaypointConnection = SameWaypointConnection
